import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:trek_bikes_app/api_config.dart';
import 'package:trek_bikes_app/session_helper.dart';
import 'package:trek_bikes_app/member_food_api.dart';

class StaffOrderPage extends StatefulWidget { const StaffOrderPage({super.key}); @override State<StaffOrderPage> createState()=>_StaffOrderPageState(); }
class _StaffOrderPageState extends State<StaffOrderPage>{ String type='DineIn'; int? tableId; final items=<int,int>{}; late Future<List<dynamic>> tables; late Future<MemberFoodPage> foods; @override void initState(){super.initState();tables=_tables();foods=MemberFoodApi.getPage(page:1,pageSize:100);} Future<List<dynamic>> _tables()async{final t=await SessionHelper.accessToken;final r=await http.get(Uri.parse('${ApiConfig.baseUrl}/api/staff/tables/available'),headers:{'Authorization':'Bearer $t'});return jsonDecode(r.body);} Future<void> _create()async{final t=await SessionHelper.accessToken;await http.post(Uri.parse('${ApiConfig.baseUrl}/api/staff/orders'),headers:{'Authorization':'Bearer $t','Content-Type':'application/json'},body:jsonEncode({'orderType':type,'tableId':type=='DineIn'?tableId:null,'items':items.entries.map((x)=>{'foodItemId':x.key,'quantity':x.value}).toList()}));if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Đã tạo đơn.')));} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Tạo đơn Staff')),body:Column(children:[DropdownButton<String>(value:type,items:const[DropdownMenuItem(value:'DineIn',child:Text('DineIn')),DropdownMenuItem(value:'TakeAway',child:Text('TakeAway'))],onChanged:(v)=>setState(()=>type=v!)),if(type=='DineIn')FutureBuilder<List<dynamic>>(future:tables,builder:(c,s)=>DropdownButton<int>(value:tableId,hint:const Text('Chọn bàn'),items:(s.data??[]).map((x)=>DropdownMenuItem(value:x['tableId'] as int,child:Text(x['tableCode']))).toList(),onChanged:(v)=>setState(()=>tableId=v))),Expanded(child:FutureBuilder<MemberFoodPage>(future:foods,builder:(c,s)=>ListView(children:(s.data?.items??[]).map((f)=>ListTile(title:Text(f.name),trailing:items.containsKey(f.foodItemId)?Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>setState(()=>items[f.foodItemId]==1?items.remove(f.foodItemId):items[f.foodItemId]=items[f.foodItemId]!-1),icon:const Icon(Icons.remove)),Text('${items[f.foodItemId]}'),IconButton(onPressed:()=>setState(()=>items[f.foodItemId]=(items[f.foodItemId]??0)+1),icon:const Icon(Icons.add))]):IconButton(onPressed:()=>setState(()=>items[f.foodItemId]=1),icon:const Icon(Icons.add_shopping_cart)))) .toList()))),FilledButton(onPressed:items.isEmpty||(type=='DineIn'&&tableId==null)?null:_create,child:const Text('Tạo đơn'))]));}
